 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Notification Preferences</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #0b1020;
       --panel: rgba(20, 28, 48, 0.92);
       --panel-border: rgba(148, 163, 184, 0.18);
       --text: #e5eefc;
       --muted: #9fb0cf;
       --accent: #7c9cff;
       --accent-strong: #5b7fff;
       --accent-soft: rgba(124, 156, 255, 0.18);
       --error: #ff8b8b;
       --shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       display: grid;
       place-items: center;
       padding: 24px;
       font-family: Arial, sans-serif;
       background:
         radial-gradient(circle at top, rgba(91, 127, 255, 0.22), transparent 35%),
         linear-gradient(180deg, #0f172a 0%, var(--bg) 100%);
       color: var(--text);
     }

     .card {
       width: min(100%, 460px);
       padding: 32px;
       border: 1px solid var(--panel-border);
       border-radius: 20px;
       background: var(--panel);
       box-shadow: var(--shadow);
       backdrop-filter: blur(12px);
     }

     h1 {
       margin: 0 0 8px;
       font-size: 1.8rem;
     }

     p {
       margin: 0 0 24px;
       color: var(--muted);
       line-height: 1.5;
     }

     .form-field {
       margin-bottom: 24px;
     }

     .form-field legend {
       margin-bottom: 14px;
       padding: 0;
       font-size: 1rem;
       font-weight: 700;
       color: var(--text);
     }

     fieldset {
       margin: 0;
       padding: 0;
       border: 0;
       min-width: 0;
     }

     .options {
       display: grid;
       gap: 12px;
     }

     .option {
       display: flex;
       align-items: center;
       gap: 12px;
       padding: 14px 16px;
       border: 1px solid rgba(148, 163, 184, 0.2);
       border-radius: 14px;
       background: rgba(15, 23, 42, 0.72);
       transition: border-color 0.2s ease, background-color 0.2s ease, transform 0.2s ease;
       cursor: pointer;
     }

     .option:hover,
     .option:focus-within {
       border-color: rgba(124, 156, 255, 0.65);
       background: rgba(27, 39, 70, 0.92);
       transform: translateY(-1px);
     }

     input[type="radio"] {
       width: 18px;
       height: 18px;
       margin: 0;
       accent-color: var(--accent-strong);
       flex: none;
     }

     button {
       width: 100%;
       border: 0;
       border-radius: 14px;
       padding: 14px 18px;
       font-size: 1rem;
       font-weight: 700;
       color: #081122;
       background: linear-gradient(135deg, #9ab3ff 0%, var(--accent-strong) 100%);
       cursor: pointer;
       transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
       box-shadow: 0 14px 30px rgba(91, 127, 255, 0.3);
     }

     button:hover,
     button:focus-visible {
       transform: translateY(-1px);
       filter: brightness(1.05);
     }

