       color: #8ff7b0;
     }
   </style>
 </head>
 <body>
   <main class="card">
     <h1>Notification Settings</h1>
     <p>Select the way you would like to receive updates.</p>

     <form id="notification-form">
       <div class="form-field">
         <fieldset>
           <legend>How do you prefer to receive notifications?</legend>
           <div class="options">
             <label class="option" for="notify-email">
               <input id="notify-email" type="radio" name="notification" value="Email" required>
               <span>Email</span>
             </label>
             <label class="option" for="notify-sms">
               <input id="notify-sms" type="radio" name="notification" value="SMS">
               <span>SMS</span>
             </label>
             <label class="option" for="notify-push">
               <input id="notify-push" type="radio" name="notification" value="Push Notifications">
               <span>Push Notifications</span>
             </label>
           </div>
         </fieldset>
       </div>

       <button type="submit">Submit</button>
       <div id="form-message" class="message" aria-live="polite"></div>
     </form>
   </main>

   <script>
     const form = document.getElementById("notification-form");
     const message = document.getElementById("form-message");

     form.addEventListener("submit", function (event) {
       event.preventDefault();

       const selected = form.querySelector('input[name="notification"]:checked');

       if (!selected) {
         message.textContent = "Please choose one notification method before submitting.";
         message.className = "message error";
         return;
       }

       message.textContent = "Preference saved: " + selected.value + ".";
       message.className = "message success";
     });
   </script>
 </body>
